//! The Unicode property names V8 accepts in `\\p{...}`, generated by
//! `findings/conformance/work/regex/tables/gen_names.py` from what node v22.22.1 (ICU 78.2,
//! Unicode 17.0) accepts, probed with every alias of Unicode 17.0's PropertyAliases.txt
//! and PropertyValueAliases.txt. Each maps to the spelling the port gives regress.

/// What a lone name in `\\p{name}` is (V8 tries a General_Category value first, then
/// `Any`, `ASCII` and `Assigned`, then a binary property, then, with `v`, a property of
/// strings).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(super) enum Lone {
    Gc(&'static str),
    Any,
    Ascii,
    Assigned,
    Binary(&'static str),
    /// A property of strings (`v` only).
    Strings(&'static str),
}

